// Mitigation: Branchless Programming
// Replaces conditional jump (JXX) with Conditional Move (CMOV)
// CMOV executes both sides, selecting result without stall.

// Standard Branch
if (a > b) {
    max_val = a;
} else {
    max_val = b;
}

// Branchless equivalent (Often compiles to CMOV)
max_val = (a > b) ? a : b;

